// The codebase digest: generated by code, never hand-written, hashed per file so a re-scan only
// re-reads what changed. It is what the profile facts and the system prompt are built from.

import { join } from "node:path";
import type { RobotRepo } from "./repo.ts";
import { type Store, readJson, sha256, writeJson } from "./store.ts";

export interface Constant {
  name: string; // "AutoRunner.ABORT_AT_S", "Tuned.centerToFront"
  value: number | null; // null = Double.NaN (not measured yet)
  expr: string;
  file: string;
  line: number;
}

export interface FileDigest {
  file: string;
  hash: string;
  constants: Constant[];
  enums: { name: string; values: string[]; line: number }[];
  methods: { name: string; line: number; comment: string }[];
}

export interface Digest {
  version: 1;
  builtAt: string;
  head: string | null;
  hash: string; // over every file hash
  files: FileDigest[];
  symbols: Record<string, number | null>;
  constants: Record<string, Constant>;
  shotTables: Record<"front" | "back", { rows: number; min: number | null; max: number | null; line: number | null }>;
  facts: { key: string; text: string; file: string; line: number }[]; // other things read from code and docs
  legApi: { actions: string[]; methods: string[]; file: string };
  autoPaths: { file: string; exists: boolean };
}

const DIGEST_VERSION = 1;

// Files whose content the tool depends on. Others are reachable through read_repo/grep.
function relevantFiles(repo: RobotRepo): string[] {
  const all = repo.textFiles("TeamCode/src/main/java").filter((f) => f.endsWith(".java"));
  const want = /\/(AutoRunner|(Sample)?AutoPaths|(Sample)?AutoBlue|(Sample)?AutoRed|Tuned|Field|MatchState|AutoAim|Yaw|Launcher|Intake|Ramp|Constants)\.java$/;
  const out = all.filter((f) => want.test(f));
  for (const f of ["team-config.yaml", "build.dependencies.gradle", "docs/BIOBUZZ_PREREQUISITES.md"]) if (repo.exists(f)) out.push(f);
  return out;
}

function lineAt(text: string, offset: number): number {
  let n = 1;
  for (let i = 0; i < offset; i++) if (text.charCodeAt(i) === 10) n++;
  return n;
}

function precedingComment(lines: string[], idx: number): string {
  const out: string[] = [];
  for (let i = idx - 1; i >= 0 && /^\s*\/\//.test(lines[i]); i--) out.unshift(lines[i].trim().replace(/^\/\/\s?/, ""));
  return out.join(" ");
}

export function digestFile(file: string, text: string): FileDigest {
  const cls = file.split("/").pop()!.replace(/\.java$/, "");
  const constants: Constant[] = [];
  const enums: FileDigest["enums"] = [];
  const methods: FileDigest["methods"] = [];
  if (file.endsWith(".java")) {
    for (const m of text.matchAll(/(?:public|private|protected)?\s*static\s+(?:final\s+)?(?:double|int|float|long)\s+(\w+)\s*=\s*([^;]+);/g)) {
      const expr = m[2].trim();
      const v = expr === "Double.NaN" ? null : Number(expr.replace(/[dDfFlL]$/, ""));
      constants.push({ name: `${cls}.${m[1]}`, value: v === null || Number.isFinite(v) ? v : null, expr, file, line: lineAt(text, m.index ?? 0) });
    }
    for (const m of text.matchAll(/enum\s+(\w+)\s*\{([^}]*)\}/g)) {
      enums.push({ name: `${cls}.${m[1]}`, values: m[2].split(",").map((s) => s.trim()).filter(Boolean), line: lineAt(text, m.index ?? 0) });
    }
    const lines = text.split("\n");
    lines.forEach((l, i) => {
      const mm = /^\s*public\s+(?:static\s+)?(?:final\s+)?[\w<>.[\], ]+\s+(\w+)\s*\(/.exec(l);
      if (mm && !/\bclass\b/.test(l)) methods.push({ name: `${cls}.${mm[1]}`, line: i + 1, comment: precedingComment(lines, i) });
    });
  }
  return { file, hash: sha256(text), constants, enums, methods };
}

// Entries of team-config.yaml that only AutoTool reads (no Java field): CAD sizes and test-drive numbers. They are
// read as `Config.<key>`; `value: null` means not filled in yet.
export const YAML_KEYS = [
  "intakeReachIn",
  "intakeWidthIn",
  "elementsPerShot",
  "rampReachIn",
  "driveAccelInS2",
  "driveDecelInS2",
  "driveLatAccelInS2",
  "driveMaxTurnDegS",
];

export function yamlConstants(cfg: string, file = "team-config.yaml"): Constant[] {
  const out: Constant[] = [];
  const lines = cfg.split("\n");
  for (const key of YAML_KEYS) {
    const i = lines.findIndex((l) => new RegExp(`^\\s+${key}:\\s*\\{`).test(l));
    if (i < 0) continue;
    const raw = /\bvalue:\s*([^,}]*)/.exec(lines[i])?.[1].trim() ?? "";
    const n = raw === "" || raw === "null" || raw === "~" ? null : Number(raw);
    out.push({ name: `Config.${key}`, value: n !== null && Number.isFinite(n) ? n : null, expr: raw || "null", file, line: i + 1 });
  }
  return out;
}

function findLine(text: string, re: RegExp): number | null {
  const m = re.exec(text);
  return m ? lineAt(text, m.index) : null;
}

export function buildDigest(repo: RobotRepo, store: Store, progress?: (msg: string) => void): Digest {
  const cacheDir = join(store.repoDir(repo.root), "digest");
  const files: FileDigest[] = [];
  const texts = new Map<string, string>();
  for (const f of relevantFiles(repo)) {
    const text = repo.readText(f);
    texts.set(f, text);
    const h = sha256(text);
    const cached = readJson<FileDigest | null>(join(cacheDir, `${h}.json`), null);
    if (cached && cached.file === f) {
      files.push(cached);
      continue;
    }
    progress?.(`reading ${f}`);
    const d = digestFile(f, text);
    writeJson(join(cacheDir, `${h}.json`), d);
    files.push(d);
  }
  const constants: Record<string, Constant> = {};
  const symbols: Record<string, number | null> = {};
  for (const fd of files) for (const c of fd.constants) {
    constants[c.name] = c;
    symbols[c.name] = c.value;
  }
  const tuned = files.find((f) => f.file.endsWith("/Tuned.java"));
  const tunedText = tuned ? (texts.get(tuned.file) ?? "") : "";
  const table = (side: "front" | "back") => {
    const rows: number[] = [];
    for (let n = 1; n <= 16; n++) {
      const k = (c: string) => symbols[`Tuned.${side}Shot${String(n).padStart(2, "0")}${c}`];
      const vals = ["Distance", "Speed", "Hood", "Feed"].map(k);
      if (vals.every((v) => typeof v === "number")) rows.push(vals[0] as number);
    }
    return {
      rows: rows.length,
      min: rows.length >= 2 ? Math.min(...rows) : null,
      max: rows.length >= 2 ? Math.max(...rows) : null,
      line: findLine(tunedText, new RegExp(`${side}Shot01Distance`)),
    };
  };
  const facts: Digest["facts"] = [];
  const cfg = texts.get("team-config.yaml");
  if (cfg) for (const c of yamlConstants(cfg)) constants[c.name] = c;
  if (cfg) {
    const l = findLine(cfg, /front = intake/);
    if (l) facts.push({ key: "intakeEnd", text: "front = intake / NECTAR launcher side", file: "team-config.yaml", line: l });
    const p = findLine(cfg, /endgame_parking:/);
    if (p) facts.push({ key: "parkRegion", text: "endgame_parking: loading_zone", file: "team-config.yaml", line: p });
  }
  const docs = texts.get("docs/BIOBUZZ_PREREQUISITES.md");
  if (docs) {
    const l = findLine(docs, /At most 4 elements/);
    if (l) facts.push({ key: "capacity", text: "Ramp: At most 4 elements, limited by the mechanism", file: "docs/BIOBUZZ_PREREQUISITES.md", line: l });
  }
  const ms = files.find((f) => f.file.endsWith("/MatchState.java"));
  if (ms) {
    const t = texts.get(ms.file) ?? "";
    const l = findLine(t, /mirrorAroundPoint\(Field\.CENTER, Field\.CENTER\)/);
    if (l) facts.push({ key: "redRotation", text: "red = PoseFactory.degrees().mirrorAroundPoint(Field.CENTER, Field.CENTER): the 180-degree rotation", file: ms.file, line: l });
  }
  const runner = files.find((f) => f.file === repo.autoRunnerRel);
  const actions = runner?.enums.find((e) => e.name === "AutoRunner.Action")?.values ?? [];
  const legMethods: string[] = [];
  if (runner) {
    const t = texts.get(runner.file) ?? "";
    if (/public Leg timeout\(double/.test(t)) legMethods.push("timeout(seconds)");
    if (/public Leg carryIntake\(double/.test(t)) legMethods.push("carryIntake(seconds)");
    if (/public Leg\(Path path, Action action\)/.test(t)) legMethods.unshift("Leg(Path, Action)");
    if (/public Leg\(Pose target, Action action\)/.test(t)) legMethods.unshift("Leg(Pose target, Action)");
  }
  const allHash = sha256(files.map((f) => `${f.file}:${f.hash}`).join("\n"));
  return {
    version: DIGEST_VERSION,
    builtAt: new Date().toISOString(),
    head: repo.head(),
    hash: allHash,
    files,
    symbols,
    constants,
    shotTables: { front: table("front"), back: table("back") },
    facts,
    legApi: { actions, methods: legMethods, file: repo.autoRunnerRel },
    autoPaths: { file: repo.autoPathsRel(), exists: repo.exists(repo.autoPathsRel()) },
  };
}

export function symbolMap(d: Digest): Map<string, number | null> {
  return new Map(Object.entries(d.symbols));
}
